package glitch

import data.glitch_lib

suspicious_keywords := {"TODO", "HACK", "FIXME", "BUG", "INSECURE"}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check comments in the parent UnitBlock
    comment := parent.comments[_]
    keyword := suspicious_keywords[_]
    glitch_lib.contains(comment.content, keyword)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious keyword found in comment indicating a potential security issue (e.g., unresolved security gap). (CWE-732)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk through all nodes in the parent UnitBlock
    walk(parent, [path, node])
    node.ir_type != "Comment"
    node.code != ""

    # Check if the node's code contains suspicious keywords
    keyword := suspicious_keywords[_]
    glitch_lib.contains(node.code, keyword)

    # Filter out false positives: ensure the keyword is in a comment context
    # by checking if the code contains comment patterns or the node is a known code element with comments
    is_valid_comment_context(node)

    result := {
        "type": "sec_susp_comm",
        "element": node,
        "path": parent.path,
        "description": "Suspicious keyword found in code comment indicating a potential security issue. (CWE-732)"
    }
}

# Helper to validate that the keyword is in a comment context
is_valid_comment_context(node) {
    # For MethodCall nodes, check if the code contains comment-like patterns
    node.ir_type == "MethodCall"
    regex.match("(?m).*#.*", node.code)
}

is_valid_comment_context(node) {
    # For FunctionCall nodes, check if the code contains comment-like patterns
    node.ir_type == "FunctionCall"
    regex.match("(?m).*#.*", node.code)
}

is_valid_comment_context(node) {
    # For other nodes, check if the code contains the keyword in a line that starts with # or has a comment pattern
    regex.match("(?m)^[[:space:]]*#.*", node.code)
}

is_valid_comment_context(node) {
    # For nodes that are not MethodCall or FunctionCall, check for block comment patterns
    regex.match("(?s)/\\*.*?\\*/", node.code)
}

